-- محتوى أوسع وأسئلة للدروس التي كانت بلا اختبار (2026-11-25)

UPDATE lessons SET content_ar = '<h2>حَرْفَا التَّاءِ وَالثَّاءِ</h2><p>التَّاءُ <b>ت</b> عَلَيْهَا نُقْطَتَانِ فَوْقَهَا.</p><p>الثَّاءُ <b>ث</b> عَلَيْهَا ثَلَاثُ نُقَاطٍ فَوْقَهَا.</p><p>كَلِمَاتٌ تَبْدَأُ بِالتَّاءِ: تُفَّاحَةٌ 🍎، تَمْرٌ 🌴</p><p>كَلِمَاتٌ تَبْدَأُ بِالثَّاءِ: ثَعْلَبٌ 🦊، ثَلْجٌ ❄️</p><p>انْظُرْ إِلَى النُّقَاطِ لِتَعْرِفَ الْحَرْفَ!</p>'
WHERE slug = 'taa-thaa';

UPDATE lessons SET content_ar = '<h2>نَقْرَأُ كَلِمَاتٍ قَصِيرَةً</h2><p>نَجْمَعُ الْحُرُوفَ لِنَقْرَأَ كَلِمَةً:</p><p>ب + ا + ب = <b>بَابٌ</b> 🚪</p><p>ق + ل + م = <b>قَلَمٌ</b> ✏️</p><p>ب + ح + ر = <b>بَحْرٌ</b> 🌊</p><p>اقْرَأِ الْحُرُوفَ وَاحِدًا وَاحِدًا، ثُمَّ اجْمَعْهَا بِسُرْعَةٍ.</p>'
WHERE slug = 'reading-words';

UPDATE lessons SET content_ar = '<h2>نَعُدُّ مِنْ سِتَّةٍ إِلَى عَشَرَةٍ</h2><p>٦ سِتَّةٌ ⭐⭐⭐⭐⭐⭐</p><p>٧ سَبْعَةٌ ⭐⭐⭐⭐⭐⭐⭐</p><p>٨ ثَمَانِيَةٌ ⭐⭐⭐⭐⭐⭐⭐⭐</p><p>٩ تِسْعَةٌ ⭐⭐⭐⭐⭐⭐⭐⭐⭐</p><p>١٠ عَشَرَةٌ ⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐</p><p>فِي يَدَيْكَ عَشَرَةُ أَصَابِعَ. عُدَّهَا مَعَنَا!</p>'
WHERE slug = 'counting-6-10';

UPDATE lessons SET content_ar = '<h2>نَجْمَعُ الْأَعْدَادَ</h2><p>الْجَمْعُ يَعْنِي أَنْ نَضُمَّ شَيْئَيْنِ مَعًا.</p><p>🍎🍎 + 🍎🍎🍎 = ٥ تُفَّاحَاتٍ</p><p>٢ + ٣ = ٥</p><p>إِذَا كَانَ مَعَكَ ٤ أَقْلَامٍ وَأَخَذْتَ قَلَمًا آخَرَ، يَصِيرُ مَعَكَ ٥ أَقْلَامٍ.</p><p>نَصِيحَةٌ: ابْدَأْ مِنَ الْعَدَدِ الْأَكْبَرِ وَعُدَّ إِلَى الْأَمَامِ.</p>'
WHERE slug = 'addition-basics';

UPDATE lessons SET content_ar = '<h2>الْكَائِنَاتُ الْحَيَّةُ وَغَيْرُ الْحَيَّةِ</h2><p>الْكَائِنُ الْحَيُّ يَتَنَفَّسُ، وَيَتَغَذَّى، وَيَنْمُو، وَيَحْتَاجُ إِلَى الْمَاءِ.</p><p>مِنَ الْكَائِنَاتِ الْحَيَّةِ: الْإِنْسَانُ، الْقِطَّةُ 🐱، الشَّجَرَةُ 🌳، الْوَرْدَةُ 🌹.</p><p>غَيْرُ الْحَيِّ لَا يَأْكُلُ وَلَا يَنْمُو: الْحَجَرُ، الْكُرْسِيُّ، الْكُرَةُ ⚽.</p><p>هَلْ تَسْتَطِيعُ أَنْ تَجِدَ ثَلَاثَةَ أَشْيَاءَ حَيَّةٍ فِي بَيْتِكَ؟</p>'
WHERE slug = 'living-nonliving';

UPDATE lessons SET content_ar = '<h2>دورة الماء في الطبيعة</h2><p><b>التبخر:</b> تسخّن الشمس ماء البحار والأنهار، فيتحول إلى بخار يصعد إلى السماء.</p><p><b>التكاثف:</b> يبرد البخار في الأعلى، فيتحول إلى قطرات صغيرة تتجمع وتكوّن الغيوم ☁️.</p><p><b>الهطول:</b> عندما تثقل القطرات تسقط مطرًا 🌧️ أو ثلجًا.</p><p><b>الجريان:</b> يجري الماء في الأنهار حتى يعود إلى البحر، وتبدأ الدورة من جديد.</p><p>كمية الماء على الأرض لا تختفي، بل تنتقل من شكل إلى شكل.</p>'
WHERE slug = 'water-cycle';

INSERT INTO quiz_questions (lesson_id, question_ar, options, correct_idx, explanation_ar, sort_order)
SELECT l.id, v.q, v.o::jsonb, v.c, v.e, v.s
FROM lessons l
JOIN (VALUES
  ('taa-thaa', 'كَمْ نُقْطَةً فَوْقَ حَرْفِ التَّاءِ؟', '["نُقْطَةٌ وَاحِدَةٌ","نُقْطَتَانِ","ثَلَاثُ نُقَاطٍ"]', 1, 'التَّاءُ فَوْقَهَا نُقْطَتَانِ.', 1),
  ('taa-thaa', 'أَيُّ كَلِمَةٍ تَبْدَأُ بِحَرْفِ الثَّاءِ؟', '["تَمْرٌ 🌴","ثَعْلَبٌ 🦊","بَيْتٌ 🏠"]', 1, 'ثَعْلَبٌ تَبْدَأُ بِالثَّاءِ.', 2),
  ('taa-thaa', 'مَا الْحَرْفُ الْأَوَّلُ فِي كَلِمَةِ تُفَّاحَةٍ؟', '["ب","ت","ث"]', 1, 'تُفَّاحَةٌ تَبْدَأُ بِالتَّاءِ.', 3),
  ('reading-words', 'كَمْ حَرْفًا فِي كَلِمَةِ قَلَمٍ؟', '["حَرْفَانِ","ثَلَاثَةُ أَحْرُفٍ","أَرْبَعَةُ أَحْرُفٍ"]', 1, 'ق + ل + م: ثَلَاثَةُ أَحْرُفٍ.', 1),
  ('reading-words', 'أَيْنَ نَجِدُ السَّمَكَ؟', '["بَحْرٌ 🌊","بَابٌ 🚪","قَلَمٌ ✏️"]', 0, 'السَّمَكُ يَعِيشُ فِي الْبَحْرِ.', 2),
  ('reading-words', 'ب + ا + ب = ؟', '["بَابٌ","بَيْتٌ","نَبَاتٌ"]', 0, 'ب + ا + ب = بَابٌ.', 3),
  ('counting-6-10', 'مَا الْعَدَدُ الَّذِي يَأْتِي بَعْدَ ٧؟', '["٦","٨","٩"]', 1, 'بَعْدَ سَبْعَةٍ يَأْتِي ثَمَانِيَةٌ.', 1),
  ('counting-6-10', 'كَمْ إِصْبَعًا فِي الْيَدَيْنِ مَعًا؟', '["٥","٨","١٠"]', 2, 'فِي كُلِّ يَدٍ خَمْسَةُ أَصَابِعَ، وَالْمَجْمُوعُ عَشَرَةٌ.', 2),
  ('counting-6-10', 'أَيُّ عَدَدٍ هُوَ الْأَكْبَرُ؟', '["٦","٩","٧"]', 1, 'تِسْعَةٌ أَكْبَرُ مِنْ سِتَّةٍ وَسَبْعَةٍ.', 3),
  ('addition-basics', '٢ + ٢ = ؟', '["٣","٤","٥"]', 1, '٢ + ٢ = ٤', 1),
  ('addition-basics', '٣ + ٤ = ؟', '["٦","٧","٨"]', 1, '٣ + ٤ = ٧', 2),
  ('addition-basics', 'مَعَ سَلْمَى ٥ تُفَّاحَاتٍ، وَأَعْطَتْهَا أُمُّهَا تُفَّاحَةً. كَمْ صَارَ مَعَهَا؟', '["٤","٥","٦"]', 2, '٥ + ١ = ٦', 3),
  ('living-nonliving', 'أَيٌّ مِمَّا يَلِي كَائِنٌ حَيٌّ؟', '["حَجَرٌ","شَجَرَةٌ","كُرْسِيٌّ"]', 1, 'الشَّجَرَةُ تَنْمُو وَتَحْتَاجُ إِلَى الْمَاءِ.', 1),
  ('living-nonliving', 'أَيٌّ مِمَّا يَلِي غَيْرُ حَيٍّ؟', '["قِطَّةٌ","وَرْدَةٌ","كُرَةٌ"]', 2, 'الْكُرَةُ لَا تَأْكُلُ وَلَا تَنْمُو.', 2),
  ('living-nonliving', 'مَاذَا يَحْتَاجُ الْكَائِنُ الْحَيُّ لِيَعِيشَ؟', '["الْمَاءَ وَالْغِذَاءَ","الْأَلْوَانَ","اللَّعِبَ فَقَطْ"]', 0, 'كُلُّ كَائِنٍ حَيٍّ يَحْتَاجُ إِلَى الْمَاءِ وَالْغِذَاءِ.', 3),
  ('water-cycle', 'ماذا يحدث للماء عندما تسخّنه الشمس؟', '["يتجمد","يتبخر","يختفي إلى الأبد"]', 1, 'الحرارة تحوّل الماء إلى بخار.', 1),
  ('water-cycle', 'كيف تتكون الغيوم؟', '["من تكاثف بخار الماء في الجو البارد","من الدخان","من الرمال"]', 0, 'يبرد البخار فيتكاثف ويكوّن الغيوم.', 2),
  ('water-cycle', 'ما اسم سقوط الماء من الغيوم مطرًا أو ثلجًا؟', '["التبخر","الهطول","التكاثف"]', 1, 'سقوط المطر والثلج اسمه الهطول.', 3)
) AS v(slug, q, o, c, e, s) ON v.slug = l.slug
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.lesson_id = l.id);
